import React from 'react';
import { Link } from 'react-router-dom';
import { FaGraduationCap, FaTimes } from 'react-icons/fa';
import './Sidebar.css';

const Sidebar = ({ items, activeTab, onTabChange, isOpen, onClose, roleTitle }) => {
  return (
    <>
      {/* Mobile overlay */}
      {isOpen && <div className="sidebar-overlay" onClick={onClose} />}

      <aside className={`sidebar ${isOpen ? 'open' : ''}`}>
        {/* Brand Logo Header to fill the top 70px space */}
        <div className="sidebar-brand-section">
          <Link to="/" className="sidebar-brand-link">
            <div className="sidebar-brand-logo-icon">
              <FaGraduationCap />
            </div>
            <div className="sidebar-brand-info">
              <span className="sidebar-brand-name">UniEvents</span>
              <span className="sidebar-brand-desc">Campus Portal</span>
            </div>
          </Link>
          {onClose && (
            <button
              type="button"
              className="sidebar-close-btn"
              onClick={onClose}
              aria-label="Close menu"
            >
              <FaTimes />
            </button>
          )}
        </div>

        <div className="sidebar-header">
          <div className="sidebar-badge">{roleTitle || 'Portal'}</div>
        </div>

        <nav className="sidebar-nav">
          <ul className="sidebar-menu">
            {items.map((item) => {
              const Icon = item.icon;
              const isActive = activeTab === item.id;
              return (
                <li key={item.id} className="sidebar-item">
                  <button
                    type="button"
                    className={`sidebar-link ${isActive ? 'active' : ''}`}
                    onClick={() => {
                      onTabChange(item.id);
                      if (onClose) onClose();
                    }}
                  >
                    {Icon && <Icon className="sidebar-item-icon" />}
                    <span className="sidebar-item-label">{item.label}</span>
                    {item.badge !== undefined && item.badge > 0 && (
                      <span className="sidebar-item-badge">{item.badge}</span>
                    )}
                  </button>
                </li>
              );
            })}
          </ul>
        </nav>
      </aside>
    </>
  );
};

export default Sidebar;
